'use strict';

/*
 * Minimal deep-merge helper.
 *
 * Vendored from deepmerge@4.3.1 (https://github.com/TehShrike/deepmerge, MIT License)
 * so we can drop the unmaintained `deepmerge` npm dependency and the (false-positive)
 * CVE reports filed against it. Ported to the project code style; the prototype-
 * poisoning guard `propertyIsUnsafe()` (added upstream in 4.2.0, the fix for
 * CVE-2026-93753 / GHSA-gcqx-w48m-w2h4) is preserved. The upstream React-element
 * special-casing and the `deepmerge.all` helper are omitted as unused here.
 */

function isMergeableObject(value) {
  return isNonNullObject(value) && !isSpecial(value);
}

function isNonNullObject(value) {
  return !!value && typeof value === 'object';
}

function isSpecial(value) {
  const stringValue = Object.prototype.toString.call(value);
  return stringValue === '[object RegExp]' || stringValue === '[object Date]';
}

function emptyTarget(val) {
  return Array.isArray(val) ? [] : {};
}

function cloneUnlessOtherwiseSpecified(value, options) {
  return (options.clone !== false && options.isMergeableObject(value))
    ? deepmerge(emptyTarget(value), value, options)
    : value;
}

function defaultArrayMerge(target, source, options) {
  return target.concat(source).map(function (element) {
    return cloneUnlessOtherwiseSpecified(element, options);
  });
}

// Not part of upstream deepmerge. Replicates deepmerge 2.x's effective array-merge
// behaviour for primitive arrays: keep the target's items, append only source items
// not already present. Unlike the upstream default (concatenate) it never duplicates
// values, and unlike an overwrite strategy it never discards the target's items when
// the incoming source array is empty. Call sites that relied on the 2.x default before
// this module was vendored pass this as `arrayMerge` to preserve that behaviour.
function dedupeArrayMerge(target, source) {
  return target.concat(source.filter(function (item) {
    return target.indexOf(item) === -1;
  }));
}

function getMergeFunction(key, options) {
  if (!options.customMerge) {
    return deepmerge;
  }
  const customMerge = options.customMerge(key);
  return typeof customMerge === 'function' ? customMerge : deepmerge;
}

function getEnumerableOwnPropertySymbols(target) {
  if (!Object.getOwnPropertySymbols) {
    return [];
  }
  return Object.getOwnPropertySymbols(target).filter(function (symbol) {
    return Object.propertyIsEnumerable.call(target, symbol);
  });
}

function getKeys(target) {
  return Object.keys(target).concat(getEnumerableOwnPropertySymbols(target));
}

function propertyIsOnObject(object, property) {
  try {
    return property in object;
  } catch (_) {
    return false;
  }
}

// Protects from prototype poisoning and unexpected merging up the prototype chain:
// a key is unsafe to merge when it exists on the target only via the prototype chain
// (e.g. __proto__, constructor), or exists but is non-enumerable.
function propertyIsUnsafe(target, key) {
  return propertyIsOnObject(target, key)
    && !(Object.hasOwn(target, key)
      && Object.propertyIsEnumerable.call(target, key));
}

function mergeObject(target, source, options) {
  const destination = {};
  if (options.isMergeableObject(target)) {
    getKeys(target).forEach(function (key) {
      destination[key] = cloneUnlessOtherwiseSpecified(target[key], options);
    });
  }
  getKeys(source).forEach(function (key) {
    if (propertyIsUnsafe(target, key)) {
      return;
    }
    if (propertyIsOnObject(target, key) && options.isMergeableObject(source[key])) {
      destination[key] = getMergeFunction(key, options)(target[key], source[key], options);
    } else {
      destination[key] = cloneUnlessOtherwiseSpecified(source[key], options);
    }
  });
  return destination;
}

function deepmerge(target, source, options) {
  options = options || {};
  options.arrayMerge = options.arrayMerge || defaultArrayMerge;
  options.isMergeableObject = options.isMergeableObject || isMergeableObject;
  // cloneUnlessOtherwiseSpecified is added to `options` so that custom arrayMerge()
  // implementations can use it. The caller may not replace it.
  options.cloneUnlessOtherwiseSpecified = cloneUnlessOtherwiseSpecified;

  const sourceIsArray = Array.isArray(source);
  const targetIsArray = Array.isArray(target);
  const sourceAndTargetTypesMatch = sourceIsArray === targetIsArray;

  if (!sourceAndTargetTypesMatch) {
    return cloneUnlessOtherwiseSpecified(source, options);
  } else if (sourceIsArray) {
    return options.arrayMerge(target, source, options);
  } else {
    return mergeObject(target, source, options);
  }
}

module.exports = deepmerge;
module.exports.dedupeArrayMerge = dedupeArrayMerge;
